  "content.alert.fentanyl-in-stimulants.body": "ਫੈਂਟਾਨਿਲ ਕੋਕੀਨ, ਮੈਥ ਅਤੇ ਦਬਾ ਕੇ ਬਣਾਈਆਂ ਗੋਲੀਆਂ ਵਿੱਚ ਮਿਲ ਰਿਹਾ ਹੈ, ਇਸ ਲਈ ਜੋ ਲੋਕ ਓਪੀਔਇਡ ਨਹੀਂ ਲੈਂਦੇ, ਉਹਨਾਂ ਦੀ ਵੀ ਓਵਰਡੋਜ਼ ਹੋ ਸਕਦੀ ਹੈ। ਜੇ ਹੋ ਸਕੇ ਤਾਂ ਟੈਸਟ ਕਰੋ, ਇਕੱਲੇ ਨਾ ਵਰਤੋ ਅਤੇ ਨਾਲੋਕਸੋਨ ਕੋਲ ਰੱਖੋ।",
