  "content.alert.medetomidine.body": "ਅਮਰੀਕਾ ਦੇ ਕੁਝ ਹਿੱਸਿਆਂ ਵਿੱਚ, ਸੁਸਤ ਕਰਨ ਵਾਲੀ ਦਵਾਈ ਮੇਡੇਟੋਮਿਡੀਨ ਨੇ ਸੜਕੀ ਫੈਂਟਾਨਿਲ ਵਿੱਚ ਜ਼ਾਈਲਾਜ਼ੀਨ ਦੀ ਥਾਂ ਵੱਡੇ ਪੱਧਰ 'ਤੇ ਲੈ ਲਈ ਹੈ। ਪੈਨਸਿਲਵੇਨੀਆ ਦੀ ਡਰੱਗ ਜਾਂਚ ਵਿੱਚ 2025 ਦੀ ਦੂਜੀ ਤਿਮਾਹੀ ਦੌਰਾਨ ਇਹ ਲਗਭਗ 95% ਫੈਂਟਾਨਿਲ ਨਮੂਨਿਆਂ ਵਿੱਚ ਮਿਲੀ, ਅਤੇ ਫ਼ਿਲਾਡੈਲਫ਼ੀਆ ਵਿੱਚ 70% ਤੋਂ ਵੱਧ ਵਿੱਚ। ਇਸ ਨੂੰ ਛੱਡਣ ਦੇ ਲੱਛਣ ਗੰਭੀਰ ਹੋ ਸਕਦੇ ਹਨ ਅਤੇ ਹਸਪਤਾਲ ਦੀ ਦੇਖਭਾਲ ਦੀ ਲੋੜ ਪੈ ਸਕਦੀ ਹੈ, ਇਸ ਲਈ ਛੇਤੀ ਡਾਕਟਰੀ ਮਦਦ ਲਓ।",
  "content.alert.medetomidine.title": "ਅਮਰੀਕਾ ਦੀ ਫੈਂਟਾਨਿਲ ਸਪਲਾਈ ਵਿੱਚ ਮੇਡੇਟੋਮਿਡੀਨ",
  "content.alert.negative-strip.body": "ਟੈਸਟ ਸਟ੍ਰਿਪਾਂ ਸਿਰਫ਼ ਖ਼ਾਸ ਪਦਾਰਥਾਂ ਨੂੰ ਲੱਭਦੀਆਂ ਹਨ ਅਤੇ ਹੋਰਾਂ ਨੂੰ ਛੱਡ ਸਕਦੀਆਂ ਹਨ ਜਾਂ ਗ਼ਲਤ ਨੈਗੇਟਿਵ ਨਤੀਜਾ ਦੇ ਸਕਦੀਆਂ ਹਨ। ਹਰ ਅਣਜਾਣ ਸਪਲਾਈ ਨਾਲ ਸਾਵਧਾਨੀ ਵਰਤੋ: ਘੱਟ ਮਾਤਰਾ ਨਾਲ ਸ਼ੁਰੂ ਕਰੋ, ਹੌਲੀ-ਹੌਲੀ ਚੱਲੋ ਅਤੇ ਨਾਲੋਕਸੋਨ ਅਤੇ ਕਿਸੇ ਵਿਅਕਤੀ ਨੂੰ ਆਪਣੇ ਨਾਲ ਰੱਖੋ।",
