  "content.alert.nitazenes.body": "ਨਾਈਟਾਜ਼ੀਨ ਓਪੀਔਇਡ ਘੱਟੋ-ਘੱਟ 37 ਦੇਸ਼ਾਂ ਵਿੱਚ ਹੈਰੋਇਨ, ਨਕਲੀ ਗੋਲੀਆਂ ਅਤੇ ਹੋਰ ਨਸ਼ਿਆਂ ਵਿੱਚ ਮਿਲੇ ਹਨ। ਫੈਂਟਾਨਿਲ ਸਟ੍ਰਿਪਾਂ ਇਹਨਾਂ ਨੂੰ ਨਹੀਂ ਫੜਦੀਆਂ, ਅਤੇ ਨਾਈਟਾਜ਼ੀਨ ਸਟ੍ਰਿਪਾਂ ਕੁਝ ਕਿਸਮਾਂ ਨੂੰ ਛੱਡ ਜਾਂਦੀਆਂ ਹਨ। ਘੱਟ ਵਰਤੋ, ਹੌਲੀ-ਹੌਲੀ ਚੱਲੋ, ਕਦੇ ਵੀ ਇਕੱਲੇ ਨਾ ਵਰਤੋ ਅਤੇ ਨਾਲੋਕਸੋਨ ਨੇੜੇ ਰੱਖੋ।",
