  "content.alert.xylazine-wounds.body": "ਜ਼ਾਈਲਾਜ਼ੀਨ (\"tranq\") ਅਜਿਹੇ ਜ਼ਖ਼ਮ ਕਰ ਸਕਦੀ ਹੈ ਜੋ ਹੌਲੀ-ਹੌਲੀ ਠੀਕ ਹੁੰਦੇ ਹਨ, ਕਈ ਵਾਰ ਟੀਕਾ ਲਾਉਣ ਵਾਲੀ ਥਾਂ ਤੋਂ ਦੂਰ ਵੀ। ਜ਼ਖ਼ਮਾਂ ਨੂੰ ਸਾਫ਼ ਅਤੇ ਢੱਕ ਕੇ ਰੱਖੋ, ਅਤੇ ਫੈਲਦੀ ਲਾਲੀ, ਬੁਖ਼ਾਰ ਜਾਂ ਕਾਲੀ ਪਈ ਚਮੜੀ ਲਈ ਡਾਕਟਰੀ ਇਲਾਜ ਲਓ। ਨਾਲੋਕਸੋਨ ਜ਼ਾਈਲਾਜ਼ੀਨ ਦਾ ਅਸਰ ਨਹੀਂ ਉਲਟਾਉਂਦਾ, ਪਰ ਓਵਰਡੋਜ਼ ਦਾ ਸ਼ੱਕ ਹੋਣ 'ਤੇ ਇਹ ਹਮੇਸ਼ਾ ਦਿਓ।",
