  "health.intro": "{substance}: ਤੁਹਾਡੀ ਆਖ਼ਰੀ ਵਰਤੋਂ ਤੋਂ ਗਿਣਿਆ ਗਿਆ। ਇਹ ਆਮ ਸਮਾਂ-ਰੇਖਾਵਾਂ ਹਨ, ਗਾਰੰਟੀ ਨਹੀਂ — ਹਰ ਕੋਈ ਆਪਣੀ ਰਫ਼ਤਾਰ ਨਾਲ ਠੀਕ ਹੁੰਦਾ ਹੈ।",
