  "hero.notStarted.caption": "ਸਾਨੂੰ ਦੱਸੋ ਕਿ ਤੁਸੀਂ ਕੀ ਪਿੱਛੇ ਛੱਡ ਰਹੇ ਹੋ, ਅਤੇ ਜਿਸ ਪਲ ਤੁਸੀਂ ਰੁਕੋਗੇ, ਇਹ ਅਸਮਾਨ ਸਾਫ਼ ਹੋਣ ਲੱਗੇਗਾ।",
  "hero.notStarted.title": "ਸਾਫ਼ ਅਸਮਾਨ ਇੱਕ ਤਾਰੀਖ਼ ਨਾਲ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ।",
