  "safety.timer.intro": "ਜੇ ਤੁਸੀਂ ਵਰਤਣ ਜਾ ਰਹੇ ਹੋ, ਤਾਂ ਇਕੱਲੇ ਨਾ ਵਰਤੋ। ਟਾਈਮਰ ਸ਼ੁਰੂ ਕਰੋ: ਜੇ ਤੁਸੀਂ ਸਮੇਂ ਸਿਰ \"ਮੈਂ ਠੀਕ ਹਾਂ\" ਨਹੀਂ ਦਬਾਉਂਦੇ, ਤਾਂ ਤੁਹਾਡਾ ਫ਼ੋਨ ਉੱਚਾ ਅਲਾਰਮ ਵਜਾਉਂਦਾ ਹੈ ਤਾਂ ਜੋ ਨੇੜੇ ਕੋਈ ਮਦਦ ਕਰ ਸਕੇ, ਅਤੇ ਤੁਸੀਂ ਇੱਕ ਟੈਪ ਨਾਲ ਆਪਣੇ ਸੰਪਰਕ ਨੂੰ ਸੁਨੇਹਾ ਭੇਜ ਸਕਦੇ ਹੋ। ਐਪ ਆਪਣੇ ਆਪ ਕਿਸੇ ਨੂੰ ਫ਼ੋਨ ਨਹੀਂ ਕਰ ਸਕਦੀ।",
  "safety.timer.lateWarning": "ਤੁਹਾਡਾ ਫ਼ੋਨ ਇਹ ਅਲਾਰਮ ਕੁਝ ਮਿੰਟ ਦੇਰ ਨਾਲ ਵਜਾ ਸਕਦਾ ਹੈ। Android ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਇਸ ਐਪ ਲਈ \"ਅਲਾਰਮ ਅਤੇ ਯਾਦ-ਦਹਾਨੀਆਂ\" ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ ਤਾਂ ਜੋ ਇਹ ਸਮੇਂ ਸਿਰ ਵੱਜੇ।",
